style.css:
@-moz-document domain("open.spotify.com") {
/* ===== FORCE IMAGE AS REAL BACKGROUND ===== */

body,
html,
.Root,
.Root__top-container,
.Root__main-view,
.main-view-container,
.main-view-container__scroll-node,
.main-view-container__scroll-node-child,
.main-home-homeContainer,
.main-home-content,
.main-nowPlayingView-nowPlayingColumn {
    background-image: url("https://i.pinimg.com/736x/56/5e/28/565e2813775e932d948f3bcb6c234d70.jpg") !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    background-color: transparent !important;
}

/* ===== REMOVE BLACK SPOTIFY OVERLAYS ===== */

div,
section,
main,
aside,
header,
footer {
    background-color: transparent !important;
}

/* ===== ADD DARK PINK TRANSPARENT LAYER ===== */

.Root__main-view::before {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.35);
    pointer-events: none;
    z-index: 0;
}

/* ===== KEEP CONTENT ABOVE OVERLAY ===== */

.Root__main-view * {
    position: relative;
    z-index: 1;
}

/* ===== GLASS EFFECT ===== */

.Root__nav-bar,
.main-yourLibraryX-libraryContainer,
.Root__now-playing-bar,
.main-card-card,
.main-trackList-trackListRow,
.main-topBar-topbarContentWrapper {
    background: rgba(255, 192, 203, 0.10) !important;
    backdrop-filter: blur(20px) !important;
    border-radius: 18px !important;
}

/* ===== WHITE TEXT ===== */

* {
    color: white !important;
}

/* ===== LIGHT PINK BUTTONS ===== */

button,
.Button,
.main-playButton-PlayButton,
.control-button,
.main-genericButton-button,
.main-topBar-button {
    background: #f7bfd7 !important;
    color: white !important;
    border: none !important;
    border-radius: 999px !important;
    box-shadow: 0 0 14px rgba(255,192,203,0.45);
}

/* ===== BUTTON HOVER ===== */

button:hover,
.main-playButton-PlayButton:hover {
    background: #f4aac9 !important;
    transform: scale(1.05);
    transition: 0.2s ease;
}

/* ===== SEARCH BAR ===== */

input,
.searchInput__input {
    background: rgba(255,255,255,0.14) !important;
    color: white !important;
    border-radius: 14px !important;
}

/* ===== SCROLLBAR ===== */

::-webkit-scrollbar-thumb {
    background: #f7bfd7 !important;
    border-radius: 10px !important;
}
}
